//! `espforge`: the command-line face of [`espforge_core`].
//!
//! The binary owns the flags, the terminal and the exit codes; everything
//! between an ESPF file and generated bytes lives in the library. Exit codes:
//! 0 success, 1 the user's input is at fault (already explained), 2 an
//! internal or IO failure.
//!
//! The commands follow one workflow: `examples` (what is available) -> `new`
//! (start a project) -> `check` (validate it) -> `gen` (write the crate) ->
//! `build` (write it and compile).

mod commands;

use std::process::ExitCode;

use clap::{CommandFactory, Parser, Subcommand};

#[derive(Parser)]
#[command(name = "espforge", version, about = "ESPF runtime pipeline tool")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Debug, Subcommand)]
enum Commands {
    /// List the embedded examples, grouped by category.
    #[command(name = "examples", after_help = "Example:\n  espforge examples")]
    Examples,

    /// Create a project from an embedded example.
    ///
    /// The example may be a short name (`blink`) or a full key
    /// (`01.Basics/blink`). The directory must be absent or empty.
    #[command(
        name = "new",
        after_help = "Examples:\n  espforge new blink my-app\n  espforge new 01.Basics/blink my-app"
    )]
    New(commands::new::NewArgs),

    /// Validate a project without writing anything.
    ///
    /// Checks the spec, the app logic and the Wokwi overlay files. It does not
    /// generate a crate: `espforge build` verifies the generated project.
    #[command(
        name = "check",
        after_help = "Examples:\n  espforge check\n  espforge check my-app\n  espforge check --example blink --chip esp32s3"
    )]
    Check(commands::check::CheckArgs),

    /// Generate the firmware project only (no cargo).
    ///
    /// Flags override the file; a `note:` says when one changes something.
    #[command(
        name = "gen",
        after_help = "Examples:\n  espforge gen\n  espforge gen hello.espf --chip esp32s3 --option alloc=false\n  espforge gen --example blink --out /tmp/hw"
    )]
    Gen(commands::generate::GenArgs),

    /// Generate the project and compile it with `cargo build`.
    #[command(
        name = "build",
        after_help = "Examples:\n  espforge build\n  espforge build --release\n  espforge build --chip esp32s3"
    )]
    Build(commands::build::BuildArgs),
}

fn main() -> ExitCode {
    match Cli::parse().command {
        Some(Commands::Examples) => commands::examples::run(),
        Some(Commands::New(args)) => commands::new::run(args),
        Some(Commands::Check(args)) => commands::check::run(args),
        Some(Commands::Gen(args)) => commands::generate::run(args),
        Some(Commands::Build(args)) => commands::build::run(args),
        // No subcommand given: show help instead of erroring.
        None => {
            Cli::command()
                .print_help()
                .expect("rendering help should not fail");
            ExitCode::SUCCESS
        }
    }
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;

    #[test]
    fn the_subcommands_are_the_workflow() {
        let cmd = Cli::command();
        let names: Vec<&str> = cmd.get_subcommands().map(|c| c.get_name()).collect();
        assert_eq!(names, ["examples", "new", "check", "gen", "build"]);
    }

    #[test]
    fn gen_accepts_a_file_or_an_example_but_not_both() {
        assert!(Cli::try_parse_from(["espforge", "gen", "hello.espf"]).is_ok());
        assert!(
            Cli::try_parse_from(["espforge", "gen", "--example", "01.Basics/helloworld"]).is_ok()
        );
        assert!(
            Cli::try_parse_from([
                "espforge",
                "gen",
                "hello.espf",
                "--example",
                "01.Basics/helloworld",
            ])
            .is_err()
        );
    }

    #[test]
    fn new_takes_an_example_and_a_directory() {
        let cli = Cli::try_parse_from(["espforge", "new", "blink", "my-app"]).unwrap();
        match cli.command {
            Some(Commands::New(args)) => {
                assert_eq!(args.example, "blink");
                assert_eq!(args.dir, PathBuf::from("my-app"));
            }
            other => panic!("expected `new`, got {other:?}"),
        }
        assert!(Cli::try_parse_from(["espforge", "new", "blink"]).is_err());
    }

    #[test]
    fn build_accepts_the_generation_flags_and_release() {
        let cli =
            Cli::try_parse_from(["espforge", "build", "--chip", "esp32s3", "--release"]).unwrap();
        match cli.command {
            Some(Commands::Build(args)) => {
                assert!(args.release);
                assert_eq!(args.generate.answers.chip.as_deref(), Some("esp32s3"));
            }
            other => panic!("expected `build`, got {other:?}"),
        }
    }

    #[test]
    fn check_takes_a_path_or_an_example_but_not_both() {
        assert!(Cli::try_parse_from(["espforge", "check", "my-app"]).is_ok());
        assert!(Cli::try_parse_from(["espforge", "check", "--example", "blink"]).is_ok());
        assert!(
            Cli::try_parse_from(["espforge", "check", "my-app", "--example", "blink"]).is_err()
        );
    }
}
